package com.alpharip.staffmod.IncidentPostMortemBoard; import java.io.File; public final class IncidentPostMortemController { private final IncidentPostMortemBoard board;private final IncidentPostMortemService service;private final IncidentPostMortemAccess access;private final File file; public IncidentPostMortemController(IncidentPostMortemBoard b,IncidentPostMortemAccess a,File f){if(b==null||a==null)throw new IllegalArgumentException("Board and access adapter required");board=b;access=a;file=f;service=new IncidentPostMortemService(b);} public IncidentPostMortemBoard getBoard(){return board;} public IncidentPostMortemService getService(){return service;} public IncidentPostMortemAccess getAccess(){return access;} public boolean load(){return file!=null&&IncidentPostMortemStorage.load(file,board);} public boolean save(){return file!=null&&IncidentPostMortemStorage.save(file,board);} }